import XCTest
@testable import AppShell
import CoreModel

/// The Live Activity description is generated by the on-device model, so these
/// tests pin the two things that decide whether the Lock Screen stays honest:
/// what we agree to show, and how often we agree to ask.
final class LiveActivitySummaryTests: XCTestCase {
    private let workspace = WorkspaceID(UUID(uuidString: "AAAAAAAA-AAAA-AAAA-AAAA-AAAAAAAAAAAA")!)
    private let threadA = AgentThreadID(UUID(uuidString: "11111111-1111-1111-1111-111111111111")!)
    private let threadB = AgentThreadID(UUID(uuidString: "22222222-2222-2222-2222-222222222222")!)

    private func active(
        _ id: AgentThreadID,
        title: String = "ship labels",
        update: String? = "Running: swift test"
    ) -> PetActiveThreadItem {
        PetActiveThreadItem(
            threadID: id,
            workspaceID: workspace,
            workspaceName: "star",
            providerName: "Grok",
            threadTitle: title,
            lastUpdatePreview: update
        )
    }

    private func finished(_ id: String, outcome: PetAttentionOutcome = .completed) -> PetAttentionItem {
        PetAttentionItem(
            id: id,
            kind: .agentOutcome(outcome),
            title: "Agent run completed",
            detail: "star - Grok - \(id)",
            workspaceName: "star",
            createdAt: Date(timeIntervalSince1970: 100),
            route: .agentThread(threadID: threadB, workspaceID: workspace),
            source: .agentThread(threadID: threadB)
        )
    }

    // MARK: - Source

    func testSourceIsNilWhenThereIsNothingToSummarize() {
        XCTAssertNil(LiveActivitySummary.source(for: .init(active: [], needsYou: [], completed: [])))
    }

    func testSourceForSingleActiveCarriesProgressText() throws {
        let source = try XCTUnwrap(LiveActivitySummary.source(
            for: .init(active: [active(threadA)], needsYou: [], completed: [])
        ))
        XCTAssertTrue(source.key.contains(threadA.value.uuidString))
        XCTAssertTrue(source.text.contains("Running: swift test"))
    }

    /// WHY: the fingerprint is what stops the model being re-run on every
    /// publish. If it changed for identical content, a chatty run would ask the
    /// sidecar to summarize on every tool line.
    func testFingerprintIsStableForIdenticalContentAndChangesWithIt() {
        XCTAssertEqual(LiveActivitySummary.fingerprint("a b c"), LiveActivitySummary.fingerprint("a b c"))
        XCTAssertNotEqual(LiveActivitySummary.fingerprint("a b c"), LiveActivitySummary.fingerprint("a b d"))
    }

    func testTerminalSourceSummarizesFinishedWork() throws {
        let source = try XCTUnwrap(LiveActivitySummary.source(
            for: .init(active: [], needsYou: [], completed: [finished("t1"), finished("t2")])
        ))
        XCTAssertTrue(source.text.contains("t1"))
        XCTAssertTrue(source.text.contains("t2"))
    }

    // MARK: - Output guard

    private func source(_ text: String) -> LiveActivitySummary.Source {
        LiveActivitySummary.Source(
            key: "k", text: text, fingerprint: LiveActivitySummary.fingerprint(text)
        )
    }

    func testAcceptsAOneSentenceAnswer() {
        let src = source("Running: swift test")
        XCTAssertEqual(
            LiveActivitySummary.sanitized("Running the Swift test suite for the pet module.", source: src),
            "Running the Swift test suite for the pet module."
        )
    }

    /// The sidecar's store-before-loss rule can hand back the raw input. Showing
    /// it would look like a summary while being none, so it must be refused.
    func testRejectsVerbatimEchoOfTheInput() {
        let src = source("Running: swift test")
        XCTAssertNil(LiveActivitySummary.sanitized("Running: swift test", source: src))
    }

    /// Compressed-dialect output and leaked scaffolding are not prose.
    func testRejectsCompressedDialectAndLeakedScaffolding() {
        let src = source("x")
        XCTAssertNil(LiveActivitySummary.sanitized("S ran tests\nC ok", source: src))
        XCTAssertNil(LiveActivitySummary.sanitized("SR1_RESPONSE: something", source: src))
        XCTAssertNil(LiveActivitySummary.sanitized("<think>hmm</think>", source: src))
        XCTAssertNil(LiveActivitySummary.sanitized("   ", source: src))
        XCTAssertNil(LiveActivitySummary.sanitized("ok", source: src), "a fragment is not a sentence")
    }

    func testCollapsesMultilineOutputAndStripsWrappingQuotes() {
        let src = source("x")
        XCTAssertEqual(
            LiveActivitySummary.sanitized("\"Fixing the login\n timeout bug.\"", source: src),
            "Fixing the login timeout bug."
        )
    }

    func testClampsOverlongOutput() throws {
        let src = source("x")
        let long = String(repeating: "a", count: 400)
        let out = try XCTUnwrap(LiveActivitySummary.sanitized(long, source: src))
        XCTAssertLessThanOrEqual(out.count, LiveActivitySummary.maximumCharacters)
    }

    /// The generated line goes on a Lock Screen, which is visible without
    /// unlocking. It must pass the same redaction as every other pet string.
    func testRedactsCredentialsThatSlipIntoTheSummary() throws {
        let src = source("x")
        let out = try XCTUnwrap(
            LiveActivitySummary.sanitized("Retrying with api_key=sk-live-1234567890 now.", source: src)
        )
        XCTAssertFalse(out.contains("sk-live-1234567890"))
    }

    // MARK: - Store / debounce

    func testCacheHitsOnlyForTheExactSameContent() {
        let store = LiveActivitySummaryStore()
        let a = source("first")
        store.store("Doing the first thing.", for: a)
        XCTAssertEqual(store.summary(for: a), "Doing the first thing.")

        let b = LiveActivitySummary.Source(key: a.key, text: "second", fingerprint: LiveActivitySummary.fingerprint("second"))
        XCTAssertNil(store.summary(for: b), "stale sentence must not describe new work")
    }

    func testDebounceStopsRepeatedGenerationForAChattyRun() {
        let store = LiveActivitySummaryStore()
        let t0 = Date(timeIntervalSince1970: 1_000)
        let a = source("first")
        XCTAssertTrue(store.shouldGenerate(for: a, now: t0))
        XCTAssertFalse(store.shouldGenerate(for: a, now: t0.addingTimeInterval(1)),
                       "already in flight")

        let b = LiveActivitySummary.Source(key: a.key, text: "second", fingerprint: LiveActivitySummary.fingerprint("second"))
        XCTAssertFalse(store.shouldGenerate(for: b, now: t0.addingTimeInterval(5)),
                       "new content inside the window must still wait")
        XCTAssertTrue(store.shouldGenerate(
            for: b, now: t0.addingTimeInterval(LiveActivitySummary.minimumRefreshInterval + 1)
        ))
    }

    func testStoredSummaryStopsFurtherGeneration() {
        let store = LiveActivitySummaryStore()
        let t0 = Date(timeIntervalSince1970: 1_000)
        let a = source("first")
        _ = store.shouldGenerate(for: a, now: t0)
        store.store("Doing the first thing.", for: a)
        XCTAssertFalse(store.shouldGenerate(
            for: a, now: t0.addingTimeInterval(LiveActivitySummary.minimumRefreshInterval + 1)
        ), "content already summarized must never be re-generated")
    }

    func testResetClearsEverythingSoAnOldSentenceCannotReappear() {
        let store = LiveActivitySummaryStore()
        let a = source("first")
        store.store("Doing the first thing.", for: a)
        store.reset()
        XCTAssertNil(store.summary(for: a))
    }

    // MARK: - Placement in the card

    func testSummaryBecomesTheDescriptionOnTheRunningCard() throws {
        let output = try XCTUnwrap(PetLiveActivityCopy.make(.init(
            active: [active(threadA)],
            needsYou: [],
            completed: [],
            summary: "Refactoring the per-surface thread binding."
        )))
        XCTAssertEqual(output.preview, "Refactoring the per-surface thread binding.")
        XCTAssertEqual(output.title, "1 Thread Running")
    }

    func testSummaryBecomesTheDescriptionOnTheTerminalCard() throws {
        let output = try XCTUnwrap(PetLiveActivityCopy.make(.init(
            active: [],
            needsYou: [],
            completed: [finished("t1"), finished("t2")],
            summary: "Two review passes finished on star."
        )))
        XCTAssertEqual(output.preview, "Two review passes finished on star.")
        XCTAssertFalse(output.preview.contains("+1 more"),
                       "the crumb list is what the summary replaces")
    }

    /// An approval is actionable; a prose sentence is not. Needs-you must keep
    /// the description slot or the user loses the only prompt to act.
    func testNeedsYouStillOutranksTheSummary() throws {
        let needs = PetAttentionItem(
            id: "cb1",
            kind: .callback(.approval, isStale: false),
            title: "Approve: Run command",
            detail: "star - Grok - mid run",
            workspaceName: "star",
            createdAt: Date(),
            route: .agentThread(threadID: threadA, workspaceID: workspace),
            source: .callback(threadID: threadA, requestID: "r1", kind: .approval)
        )
        let output = try XCTUnwrap(PetLiveActivityCopy.make(.init(
            active: [active(threadA)],
            needsYou: [needs],
            completed: [],
            summary: "Refactoring the per-surface thread binding."
        )))
        XCTAssertTrue(output.preview.hasPrefix("Needs you"))
    }

    /// No model, no regression: the card keeps the progress line it always had.
    func testWithoutASummaryTheDeterministicPreviewIsUnchanged() throws {
        let row = active(threadA)
        let output = try XCTUnwrap(PetLiveActivityCopy.make(.init(
            active: [row], needsYou: [], completed: [], summary: nil
        )))
        XCTAssertEqual(output.preview, "Running: swift test")
    }
}
